var NL=String.fromCharCode(10);
const allCalendarItems = $('📅 Google Calendar - I dag').all();
const now = new Date();
const today = new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Copenhagen',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
const yesterday = new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Copenhagen',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(now.getTime()-86400000));
const todayLabel = new Intl.DateTimeFormat('da-DK',{timeZone:'Europe/Copenhagen',weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(now);
function hm(dt){ return new Date(dt).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Copenhagen'}); }
const calendarItems = allCalendarItems.map(function(i){return i.json;}).filter(function(e){ var d=e.start && (e.start.dateTime||e.start.date); if(!d) return false; return String(d).slice(0,10)===today; });
var events = calendarItems.length ? calendarItems.map(function(e){ var t=e.start.dateTime?hm(e.start.dateTime):'Hele dagen'; return '• '+t+': '+(e.summary||'Ingen titel'); }).join(NL) : '• Ingen kalenderbegivenheder i dag';
var logRows = $('📋 Hent Task Log').all().map(function(i){return i.json;}).filter(function(r){return r && r.task;});
function actOf(r){ return (r.actual_min!==undefined && r.actual_min!==null && r.actual_min!=='') ? Number(r.actual_min) : null; }
var unfinished = logRows.filter(function(r){ return r.log_date===yesterday && r.done!==true && actOf(r)===null; });
var unfinishedText = unfinished.length ? unfinished.map(function(r){ return '• '+r.task+(r.task_type?(' ('+r.task_type+')'):''); }).join(NL) : '';
const systemPrompt = [
'Du er Daniels personlige morgenassistent. Du er præcis, motiverende og handlingsorienteret.',
'',
'Skriv ALTID korrekt dansk med æ, ø og å. Brug rigtige danske bogstaver — aldrig ae/oe/aa.',
'',
'Giv en struktureret morgenbriefing baseret på dagens kalender og eventuelle uafsluttede opgaver fra i går.',
'',
'Format (Telegram Markdown — brug *fed*):',
'',
'🌅 *God morgen, Daniel!*',
'[En kort energisk hilsen — maks 1 sætning]',
'',
'🗓️ *Dagens program*',
'[Alle kalenderbegivenheder med tid, eller: Ingen aftaler i dag]',
'',
'⏳ *Uafsluttet fra i går*',
'[KUN hvis der er uafsluttede opgaver fra i går i konteksten: list dem kort og tilbyd venligt at planlægge dem i dag (Daniel kan svare med dem). Hvis der ingen er, så udelad HELE dette afsnit inkl. overskriften.]',
'',
'🎯 *Fokus i dag*',
'[Hvad kræver mest opmærksomhed? Hvad skal forberedes?]',
'',
'💡 *Dagens læring*',
'[En konkret anbefaling — roter mellem AI/tech, studie, produktivitet, personlig udvikling]',
'',
'🚀 *Motivation*',
'[Maks 2 sætninger — personlig og energisk]',
'',
'📋 *Planlæg din dag*',
'Svar på denne besked med din todo-liste, så estimerer jeg tiden, lægger den udenom dine møder og foreslår en plan til din kalender.',
'',
'Gengiv afsnittet Planlæg din dag ordret. Maks 340 ord. Undgå KUN ubalancerede Markdown-styringstegn (* _ ` [ ]) — brug ALTID korrekte danske bogstaver æ ø å.'
].join(NL);
const carryBlock = unfinished.length ? (NL+NL+'Uafsluttede opgaver fra i går (ikke markeret som udført):'+NL+unfinishedText) : (NL+NL+'Ingen uafsluttede opgaver fra i går.');
const userContent = 'Dato: '+todayLabel+NL+NL+'Kalender i dag:'+NL+events+carryBlock;
return [{ json: { payload: JSON.stringify({ model:'claude-sonnet-4-6', max_tokens:1024, system: systemPrompt, messages:[{ role:'user', content: userContent }] }) } }];
